package com.abdickers.realms;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.provider.Settings;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import java.util.*;

public final class SettingsActivity extends Activity {
 private LinearLayout root;
 private final Map<String,EditText> fields=new LinkedHashMap<>();
 private final Map<String,EditText> secrets=new LinkedHashMap<>();
 private Switch wifi;
 private String googleRealm="work";
 private String wifiRealm="home";
 @Override protected void onCreate(Bundle state){super.onCreate(state);if(state!=null){googleRealm=state.getString("google_realm","work");wifiRealm=state.getString("wifi_realm","home");}ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,32,24,24);root.setBackgroundColor(0xFF171D23);scroll.addView(root);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets bars=i.getInsets(WindowInsets.Type.systemBars());root.setPadding(24,bars.top+24,24,bars.bottom+24);return i;});
  heading("Accounts & preferences");button("Home and Work · sign in with Google",()->startActivity(new Intent(this,AccountActivity.class)));label("Work and Home use separate data. Saved information is visible on your unlocked home screen. No banking or Warcraft is connected.");
  button("Add widget to the home screen",()->{android.appwidget.AppWidgetManager manager=getSystemService(android.appwidget.AppWidgetManager.class);if(manager.isRequestPinAppWidgetSupported())manager.requestPinAppWidget(new ComponentName(this,CommandWidget.class),null,null);else new AlertDialog.Builder(this).setMessage("Long-press the home screen → Widgets → Middle-earth Command.").setPositiveButton("OK",null).show();});
  button("Customize Work tools",()->startActivity(new Intent(this,ManageLinksActivity.class).putExtra("realm","work")));button("Customize Home tools",()->startActivity(new Intent(this,ManageLinksActivity.class).putExtra("realm","home")));
  heading("Automatic mode");label("Manual Home/Work stays selected until you tap Auto. Known Wi-Fi takes priority over the schedule. Outside work hours, Auto selects Home. Background checks are approximately every 30 minutes and may be delayed by Android.");
  wifi=new Switch(this);wifi.setText("Recognize configured Wi-Fi networks");wifi.setTextColor(0xFFE4EAF2);wifi.setChecked(WidgetState.prefs(this).getBoolean("wifi_enabled",false));root.addView(wifi);
  field("home_wifi","Home Wi-Fi names · one per line","");button("Use current Wi-Fi for Home",()->captureWifi("home"));field("work_wifi","Work Wi-Fi names · one per line","");button("Use current Wi-Fi for Work",()->captureWifi("work"));field("days","Work days","1,2,3,4,5");fields.get("days").setFocusable(false);fields.get("days").setOnClickListener(v->chooseDays());field("start_text","Work starts","09:00");field("end_text","Work ends","17:00");for(String key:List.of("start_text","end_text")){fields.get(key).setFocusable(false);fields.get(key).setOnClickListener(v->chooseTime(key));}
  button("Allow Wi-Fi recognition",()->{new AlertDialog.Builder(this).setMessage("Android treats Wi-Fi names as location-sensitive. This option reads the connected network name only; it does not collect GPS coordinates. Allow location while using the app first. For automatic Wi-Fi selection while the app is closed, separately choose Allow all the time in Android’s app permissions. Without it, schedule and manual switching still work.").setPositiveButton("Continue",(d,w)->requestPermissions(new String[]{Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.ACCESS_FINE_LOCATION},22)).setNegativeButton("Cancel",null).show();});
  button("Android background location settings",()->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+getPackageName()))));
  button("Save switching preferences",this::saveSwitching);
  LinearLayout normal=root,developer=new LinearLayout(this);developer.setOrientation(LinearLayout.VERTICAL);developer.setVisibility(View.GONE);button("Developer options",()->developer.setVisibility(developer.getVisibility()==View.GONE?View.VISIBLE:View.GONE));root.addView(developer);root=developer;
  heading("Calendar");label("Uses Android’s locally synced calendars. Specify each account email so Work events do not appear in Home. Reads only the selected day, up to 20 events.");field("work_calendar","Work calendar account email","");field("home_calendar","Home calendar account email","");button("Allow calendar access",()->requestPermissions(new String[]{Manifest.permission.READ_CALENDAR},23));
  heading("The Ravens · Google mail");label("Authorize Gmail directly on this phone. This app reads at most eight unread inbox summaries from the last seven days per Refresh; it cannot send or delete mail. Google manages the token cache. Calendar access above remains separate.");
  field("work_google_email","Work Google account","dickersona@76fireworks.com");button("Authorize Work Gmail",()->connectGoogle("work"));
  field("home_google_email","Home Google account","abdickers@gmail.com");button("Authorize Home Gmail",()->connectGoogle("home"));
  heading("Secure Work service setup");label("Prepare a public setup request, then import the encrypted reply. Only this phone can decrypt it, and the app verifies its publisher signature. No API keys need to be copied into chat or included in the APK.");button("Prepare Work setup request",()->startActivity(new Intent(this,SetupActivity.class).putExtra("prepare",true)));button("Import encrypted Work connections",()->startActivity(new Intent(this,SetupActivity.class)));
  heading("Work services · advanced connection setup");label("These native readers are not connected to your ChatGPT integrations yet. Only enter credentials you have authorized for this app. They are encrypted with Android Keystore and never included in the APK. Blank fields keep an existing credential. No service is queried merely by opening settings.");
  field("vercel_team","Vercel team ID · team_…","");secret("vercel","Vercel API token");field("jira_email","Jira account email","");secret("jira","Jira API token");secret("slack","Slack user token with search:read");secret("celigo","Celigo production API token");
  button("Save settings",this::save);
  root=normal;
  button("Disconnect services & clear saved feeds",()->new AlertDialog.Builder(this).setMessage("Remove this app’s saved credentials and cached feeds? Provider tokens are not revoked at the provider.").setPositiveButton("Clear",(d,w)->{Connections.invalidate(this);Vault.clear(this);WidgetState.prefs(this).edit().putBoolean("work_google_connected",false).putBoolean("home_google_connected",false).putBoolean("work_google_calendar_connected",false).putBoolean("home_google_calendar_connected",false).commit();CommandWidget.updateAll(this);Toast.makeText(this,"Connections and saved feeds cleared",Toast.LENGTH_LONG).show();}).setNegativeButton("Cancel",null).show());
 }
 private void heading(String title){TextView t=new TextView(this);t.setText(title);t.setTextSize(22);t.setTextColor(0xFFE8EDF4);t.setPadding(0,18,0,10);root.addView(t);}
 private void chooseTime(String key){int current=minutes(fields.get(key).getText().toString());new TimePickerDialog(this,(view,hour,minute)->fields.get(key).setText(String.format(Locale.ROOT,"%02d:%02d",hour,minute)),current/60,current%60,android.text.format.DateFormat.is24HourFormat(this)).show();}
 private void chooseDays(){String[] names={"Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"};Set<String> selected=new HashSet<>(Arrays.asList(fields.get("days").getText().toString().split(",")));boolean[] checked=new boolean[7];for(int n=0;n<7;n++)checked[n]=selected.contains(Integer.toString(n+1));new AlertDialog.Builder(this).setTitle("Work days").setMultiChoiceItems(names,checked,(dialog,which,value)->checked[which]=value).setPositiveButton("Done",(dialog,which)->{StringJoiner days=new StringJoiner(",");for(int n=0;n<7;n++)if(checked[n])days.add(Integer.toString(n+1));fields.get("days").setText(days.toString());}).setNegativeButton("Cancel",null).show();}
 private void captureWifi(String realm){wifiRealm=realm;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=android.content.pm.PackageManager.PERMISSION_GRANTED){new AlertDialog.Builder(this).setMessage("Android requires location permission to read the connected Wi-Fi name. This app does not read GPS coordinates.").setPositiveButton("Continue",(d,w)->requestPermissions(new String[]{Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.ACCESS_FINE_LOCATION},31)).setNegativeButton("Cancel",null).show();return;}String name=WidgetState.currentWifi(this);if(name.isEmpty()){new AlertDialog.Builder(this).setMessage("Connect to Wi-Fi and turn on Android Location to use the current network. You can also type the Wi-Fi name above.").setPositiveButton("OK",null).show();return;}String other=realm.equals("home")?"work":"home";Set<String> otherNames=ModePolicy.networks(fields.get(other+"_wifi").getText().toString());if(otherNames.contains(name)){new AlertDialog.Builder(this).setMessage("This network is already assigned to "+other+". Move it to "+realm+"?").setPositiveButton("Move",(d,w)->{Set<String> remaining=new LinkedHashSet<>(otherNames);remaining.remove(name);fields.get(other+"_wifi").setText(String.join("\n",remaining));addWifi(realm,name);}).setNegativeButton("Cancel",null).show();return;}addWifi(realm,name);}
 private void addWifi(String realm,String name){Set<String> names=new LinkedHashSet<>(ModePolicy.networks(fields.get(realm+"_wifi").getText().toString()));names.add(name);fields.get(realm+"_wifi").setText(String.join("\n",names));wifi.setChecked(true);Toast.makeText(this,"Added. Save switching preferences to apply.",Toast.LENGTH_LONG).show();}
 void saveSwitching(){try{int start=minutes(fields.get("start_text").getText().toString()),end=minutes(fields.get("end_text").getText().toString());if(start==end)throw new IllegalArgumentException("Work start and end must differ.");String days=fields.get("days").getText().toString();if(!days.isEmpty()&&!days.matches("[1-7](,[1-7])*"))throw new IllegalArgumentException("Choose valid work days.");Set<String> overlap=new HashSet<>(ModePolicy.networks(fields.get("home_wifi").getText().toString()));overlap.retainAll(ModePolicy.networks(fields.get("work_wifi").getText().toString()));if(!overlap.isEmpty())throw new IllegalArgumentException("A Wi-Fi network cannot belong to both Home and Work.");WidgetState.prefs(this).edit().putBoolean("wifi_enabled",wifi.isChecked()).putInt("start",start).putInt("end",end).putString("start_text",fields.get("start_text").getText().toString()).putString("end_text",fields.get("end_text").getText().toString()).putString("days",days).putString("home_wifi",fields.get("home_wifi").getText().toString().trim()).putString("work_wifi",fields.get("work_wifi").getText().toString().trim()).commit();CommandWidget.updateAll(this);Toast.makeText(this,"Saved. Tap Auto to use your schedule and Wi-Fi rules.",Toast.LENGTH_LONG).show();}catch(IllegalArgumentException error){new AlertDialog.Builder(this).setMessage(error.getMessage()).setPositiveButton("OK",null).show();}}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==31&&checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==android.content.pm.PackageManager.PERMISSION_GRANTED)captureWifi(wifiRealm);}
 private void label(String value){TextView t=new TextView(this);t.setText(value);t.setTextSize(14);t.setTextColor(0xFFCFDAE9);root.addView(t);}
 private void field(String key,String title,String fallback){label(title);EditText input=new EditText(this);input.setTextColor(0xFFE4EAF2);input.setText(WidgetState.prefs(this).getString(key,fallback));if(key.endsWith("wifi")){input.setMinLines(2);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);}else input.setSingleLine();root.addView(input);fields.put(key,input);}
 private void secret(String key,String title){label(title);EditText input=new EditText(this);input.setTextColor(0xFFE4EAF2);input.setHint("Not changed");input.setHintTextColor(0xFFADBCCC);input.setSingleLine();input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);input.setSaveEnabled(false);input.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);root.addView(input);secrets.put(key,input);}
 private void button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setTextColor(0xFFE5ECF4);b.setBackgroundResource(R.drawable.royal_button);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,10,0,6);b.setLayoutParams(lp);root.addView(b);b.setOnClickListener(v->action.run());}
 private void save(){try{int start=minutes(fields.get("start_text").getText().toString()),end=minutes(fields.get("end_text").getText().toString());if(start==end)throw new IllegalArgumentException("Work start and end must differ.");String days=fields.get("days").getText().toString().trim();if(!days.matches("[1-7](,[1-7])*"))throw new IllegalArgumentException("Use work-day numbers separated by commas, such as 1,2,3,4,5.");Set<String> overlap=new HashSet<>(ModePolicy.networks(fields.get("home_wifi").getText().toString()));overlap.retainAll(ModePolicy.networks(fields.get("work_wifi").getText().toString()));if(!overlap.isEmpty())throw new IllegalArgumentException("A Wi-Fi network cannot belong to both Home and Work.");boolean connectionChanged=false;for(String connection:List.of("work_calendar","home_calendar","vercel_team","jira_email","work_google_email","home_google_email"))if(!fields.get(connection).getText().toString().trim().equals(WidgetState.prefs(this).getString(connection,"")))connectionChanged=true;for(Map.Entry<String,EditText> e:secrets.entrySet()){String value=e.getValue().getText().toString().trim();if(!value.isEmpty()){if(value.contains("\n")||value.contains("\r"))throw new IllegalArgumentException("Credentials must not contain line breaks.");connectionChanged=true;Vault.put(this,e.getKey(),value);}e.getValue().setText("");}android.content.SharedPreferences.Editor edit=WidgetState.prefs(this).edit().putBoolean("wifi_enabled",wifi.isChecked()).putInt("start",start).putInt("end",end);for(Map.Entry<String,EditText> e:fields.entrySet())edit.putString(e.getKey(),e.getValue().getText().toString().trim());edit.commit();if(connectionChanged)Connections.invalidate(this);CommandWidget.updateAll(this);Toast.makeText(this,"Saved. Tap Auto on the widget to use these rules.",Toast.LENGTH_LONG).show();}catch(Exception e){new AlertDialog.Builder(this).setMessage(e instanceof IllegalArgumentException?e.getMessage():"Could not save encrypted credentials. Existing settings retained.").setPositiveButton("OK",null).show();}}

 private void connectGoogle(String realm){String email=fields.get(realm+"_google_email").getText().toString().trim();if(!email.matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+")){new AlertDialog.Builder(this).setMessage("Enter the account email first.").setPositiveButton("OK",null).show();return;}googleRealm=realm;if(!email.equals(GoogleConnection.email(this,realm))){WidgetState.prefs(this).edit().putString(realm+"_google_email",email).putBoolean(realm+"_google_connected",false).commit();Connections.invalidate(this);}GoogleConnection.connect(this,realm,this::googleComplete,this::googleFailed);}
 private void googleComplete(){Connections.invalidate(this);CommandWidget.updateAll(this);Toast.makeText(this,"Mail permission granted. Select The Ravens and tap Refresh.",Toast.LENGTH_LONG).show();}
 private void googleFailed(String message){new AlertDialog.Builder(this).setMessage(message).setPositiveButton("OK",null).show();}
 @Override protected void onSaveInstanceState(Bundle state){state.putString("google_realm",googleRealm);state.putString("wifi_realm",wifiRealm);super.onSaveInstanceState(state);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==GoogleConnection.REQUEST_MAIL){if(result==RESULT_OK&&data!=null)GoogleConnection.finish(this,googleRealm,data,this::googleComplete,this::googleFailed);else googleFailed("Google permission was not granted.");}}
 static int minutes(String raw){if(!raw.matches("(?:[01]\\d|2[0-3]):[0-5]\\d"))throw new IllegalArgumentException("Use 24-hour time, such as 09:00 or 17:30.");return Integer.parseInt(raw.substring(0,2))*60+Integer.parseInt(raw.substring(3));}
}
